create policy "platform admin reads products" on public.products for select to authenticated using(public.is_platform_admin());
create policy "platform admin reads orders" on public.orders for select to authenticated using(public.is_platform_admin());
create policy "platform admin reads customers" on public.customers for select to authenticated using(public.is_platform_admin());
create policy "platform admin reads categories" on public.categories for select to authenticated using(public.is_platform_admin());
create policy "platform admin reads audit" on public.audit_logs for select to authenticated using(public.is_platform_admin());
create or replace function public.admin_set_store_status(p_store_id uuid,p_status text,p_reason text default null) returns void language plpgsql security definer set search_path=public as $$declare old_status text;begin if not public.is_platform_admin() then raise exception 'Accès administrateur requis';end if;if p_status not in('DRAFT','PUBLISHED','SUSPENDED','ARCHIVED')then raise exception 'Statut invalide';end if;select status into old_status from stores where id=p_store_id for update;if old_status is null then raise exception 'Boutique introuvable';end if;update stores set status=p_status,updated_at=now() where id=p_store_id;insert into audit_logs(user_id,action,entity_type,entity_id,metadata)values(auth.uid(),'ADMIN_STORE_STATUS','STORE',p_store_id,jsonb_build_object('old_status',old_status,'new_status',p_status,'reason',p_reason));end;$$;
create or replace function public.admin_archive_product(p_product_id uuid,p_reason text default null) returns void language plpgsql security definer set search_path=public as $$begin if not public.is_platform_admin() then raise exception 'Accès administrateur requis';end if;update products set status='ARCHIVED',updated_at=now() where id=p_product_id;if not found then raise exception 'Produit introuvable';end if;insert into audit_logs(user_id,action,entity_type,entity_id,metadata)values(auth.uid(),'ADMIN_PRODUCT_ARCHIVE','PRODUCT',p_product_id,jsonb_build_object('reason',p_reason));end;$$;
grant execute on function public.admin_set_store_status(uuid,text,text) to authenticated;grant execute on function public.admin_archive_product(uuid,text) to authenticated;notify pgrst,'reload schema';
